  1	package com.loja.orderservice.service;
  2	
  3	import com.fasterxml.jackson.core.JsonProcessingException;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.loja.orderservice.domain.entity.Customer;
  6	import com.loja.orderservice.domain.entity.Notification;
  7	import com.loja.orderservice.domain.entity.Order;
  8	import com.loja.orderservice.domain.entity.Product;
  9	import com.loja.orderservice.domain.enums.*;
 10	import com.loja.orderservice.dto.CheckoutSummary;
 11	import com.loja.orderservice.dto.CheckoutSummaryRequest;
 12	import com.loja.orderservice.dto.OrderResponse;
 13	import com.loja.orderservice.dto.PaymentNotificationRequest;
 14	import com.loja.orderservice.exception.OrderServiceException;
 15	import com.loja.orderservice.repository.CustomerRepository;
 16	import com.loja.orderservice.repository.NotificationRepository;
 17	import com.loja.orderservice.repository.OrderRepository;
 18	import com.loja.orderservice.repository.ProductRepository;
 19	import com.loja.orderservice.util.CurrencyUtils;
 20	import lombok.RequiredArgsConstructor;
 21	import org.springframework.http.HttpStatus;
 22	import org.springframework.stereotype.Service;
 23	import org.springframework.transaction.annotation.Transactional;
 24	import java.math.BigDecimal;
 25	import java.time.Instant;
 26	import java.util.LinkedHashMap;
 27	import java.util.List;
 28	import java.util.Map;
 29	import java.util.Optional;
 30	
 31	@Service
 32	@RequiredArgsConstructor
 33	public class OrderService {
 34	    private static final long PAYMENT_TIMEOUT_HOURS = 48;
 35	
 36	    private final OrderRepository orderRepository;
 37	    private final CustomerRepository customerRepository;
 38	    private final NotificationRepository notificationRepository;
 39	    private final ProductRepository productRepository;
 40	    private final CheckoutService checkoutService;
 41	    private final ObjectMapper objectMapper;
 42	
 43	    @Transactional
 44	    public OrderResponse createOrder(CheckoutSummaryRequest request) {
 45	        CheckoutSummary summary = checkoutService.calculateSummary(request);
 46	
 47	        Order order = Order.builder()
 48	                .customerCpf(request.getCustomer().getCpf())
 49	                .customerEmail(request.getCustomer().getEmail())
 50	                .status(OrderStatus.AWAITING_PAYMENT)
 51	                .createdAt(Instant.now())
 52	                .summaryJson(serializeSummary(summary))
 53	                .itemsJson(serializeItems(request.getItems()))
 54	                .build();
 55	
 56	        order = orderRepository.save(order);
 57	
 58	        return mapOrderToResponse(order);
 59	    }
 60	
 61	    @Transactional
 62	    public OrderResponse processPayment(String orderId, PaymentNotificationRequest paymentRequest) {
 63	        Optional<Order> orderOpt = orderRepository.findById(orderId);
 64	
 65	        if (orderOpt.isEmpty()) {
 66	            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
 67	        }
 68	
 69	        Order order = orderOpt.get();
 70	
 71	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
 72	            if (order.getTransactionId() != null &&
 73	                order.getTransactionId().equals(paymentRequest.getTransactionId())) {
 74	                return mapOrderToResponse(order);
 75	            }
 76	            throw new OrderServiceException("OPERATION_NOT_ALLOWED", "Order is not awaiting payment", HttpStatus.CONFLICT);
 77	        }
 78	
 79	        if (paymentRequest.getTransactionId() == null || paymentRequest.getTransactionId().isEmpty() ||
 80	            paymentRequest.getPaidAt() == null) {
 81	            throw new OrderServiceException("INVALID_ORDER", "Missing transactionId or paidAt", HttpStatus.UNPROCESSABLE_ENTITY);
 82	        }
 83	
 84	        Instant paymentTime = paymentRequest.getPaidAt();
 85	        Instant orderTime = order.getCreatedAt();
 86	        long hoursDiff = (paymentTime.getEpochSecond() - orderTime.getEpochSecond()) / 3600;
 87	
 88	        if (hoursDiff > PAYMENT_TIMEOUT_HOURS) {
 89	            order.setStatus(OrderStatus.CANCELLED);
 90	            orderRepository.save(order);
 91	            throw new OrderServiceException("ORDER_EXPIRED", "Payment timeout", HttpStatus.CONFLICT);
 92	        }
 93	
 94	        CheckoutSummary summary = deserializeSummary(order.getSummaryJson());
 95	        List<Map<String, Object>> items;
 96	        try {
 97	            @SuppressWarnings("unchecked")
 98	            List<Map<String, Object>> itemsList = objectMapper.readValue(order.getItemsJson(), List.class);
 99	            items = itemsList;
100	        } catch (JsonProcessingException e) {
101	            throw new RuntimeException("Failed to deserialize items", e);
102	        }
103	
104	        List<Product> products = getProductsForOrder(items);
105	
106	        for (int i = 0; i < items.size(); i++) {
107	            @SuppressWarnings("unchecked")
108	            Map<String, Object> item = items.get(i);
109	            String sku = (String) item.get("sku");
110	            Long quantity = ((Number) item.get("quantity")).longValue();
111	
112	            Optional<Product> productOpt = productRepository.findById(sku);
113	            if (productOpt.isEmpty() || productOpt.get().getStock() < quantity) {
114	                order.setStatus(OrderStatus.CANCELLED);
115	                orderRepository.save(order);
116	                createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
117	                throw new OrderServiceException("INSUFFICIENT_STOCK", "Insufficient stock", HttpStatus.CONFLICT);
118	            }
119	        }
120	
121	        order.setStatus(OrderStatus.PAID);
122	        order.setPaidAt(paymentTime);
123	        order.setTransactionId(paymentRequest.getTransactionId());
124	        order = orderRepository.save(order);
125	
126	        for (int i = 0; i < items.size(); i++) {
127	            @SuppressWarnings("unchecked")
128	            Map<String, Object> item = items.get(i);
129	            String sku = (String) item.get("sku");
130	            Long quantity = ((Number) item.get("quantity")).longValue();
131	
132	            Product product = products.get(i);
133	            product.setStock(product.getStock() - quantity);
134	            productRepository.save(product);
135	        }
136	
137	        String cpf = order.getCustomerCpf();
138	        Optional<Customer> customerOpt = customerRepository.findById(cpf);
139	        Customer customer;
140	        if (customerOpt.isEmpty()) {
141	            customer = Customer.builder()
142	                    .cpf(cpf)
143	                    .creditBalance(summary.getNextPurchaseCredit())
144	                    .build();
145	        } else {
146	            customer = customerOpt.get();
147	            customer.setCreditBalance(CurrencyUtils.add(customer.getCreditBalance(),
148	                    summary.getNextPurchaseCredit()));
149	        }
150	        customerRepository.save(customer);
151	
152	        createNotification(cpf, NotificationType.PAYMENT_APPROVED, orderId);
153	
154	        return mapOrderToResponse(order);
155	    }
156	
157	    @Transactional
158	    public OrderResponse shipOrder(String orderId, String trackingCode) {
159	        Optional<Order> orderOpt = orderRepository.findById(orderId);
160	
161	        if (orderOpt.isEmpty()) {
162	            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
163	        }
164	
165	        Order order = orderOpt.get();
166	
167	        if (trackingCode == null || trackingCode.isEmpty()) {
168	            throw new OrderServiceException("INVALID_ORDER", "Tracking code is required", HttpStatus.UNPROCESSABLE_ENTITY);
169	        }
170	
171	        if (order.getStatus() != OrderStatus.PAID) {
172	            throw new OrderServiceException("OPERATION_NOT_ALLOWED", "Order is not paid", HttpStatus.CONFLICT);
173	        }
174	
175	        order.setStatus(OrderStatus.SHIPPED);
176	        order.setTrackingCode(trackingCode);
177	        order = orderRepository.save(order);
178	
179	        createNotification(order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId);
180	
181	        return mapOrderToResponse(order);
182	    }
183	
184	    @Transactional
185	    public OrderResponse deliverOrder(String orderId) {
186	        Optional<Order> orderOpt = orderRepository.findById(orderId);
187	
188	        if (orderOpt.isEmpty()) {
189	            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
190	        }
191	
192	        Order order = orderOpt.get();
193	
194	        if (order.getStatus() != OrderStatus.SHIPPED) {
195	            throw new OrderServiceException("OPERATION_NOT_ALLOWED", "Order is not shipped", HttpStatus.CONFLICT);
196	        }
197	
198	        order.setStatus(OrderStatus.DELIVERED);
199	        order = orderRepository.save(order);
200	
201	        return mapOrderToResponse(order);
202	    }
203	
204	    @Transactional
205	    public OrderResponse cancelOrder(String orderId) {
206	        Optional<Order> orderOpt = orderRepository.findById(orderId);
207	
208	        if (orderOpt.isEmpty()) {
209	            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
210	        }
211	
212	        Order order = orderOpt.get();
213	
214	        if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
215	            throw new OrderServiceException("OPERATION_NOT_ALLOWED", "Order cannot be cancelled after shipment", HttpStatus.CONFLICT);
216	        }
217	
218	        if (order.getStatus() == OrderStatus.PAID) {
219	            List<Map<String, Object>> items;
220	            try {
221	                @SuppressWarnings("unchecked")
222	                List<Map<String, Object>> itemsList = objectMapper.readValue(order.getItemsJson(), List.class);
223	                items = itemsList;
224	            } catch (JsonProcessingException e) {
225	                throw new RuntimeException("Failed to deserialize items", e);
226	            }
227	
228	            for (var item : items) {
229	                String sku = (String) item.get("sku");
230	                Long quantity = ((Number) item.get("quantity")).longValue();
231	
232	                Optional<Product> productOpt = productRepository.findById(sku);
233	                if (productOpt.isPresent()) {
234	                    Product product = productOpt.get();
235	                    product.setStock(product.getStock() + quantity);
236	                    productRepository.save(product);
237	                }
238	            }
239	
240	            CheckoutSummary summary = deserializeSummary(order.getSummaryJson());
241	            String cpf = order.getCustomerCpf();
242	            Optional<Customer> customerOpt = customerRepository.findById(cpf);
243	            if (customerOpt.isPresent()) {
244	                Customer customer = customerOpt.get();
245	                customer.setCreditBalance(CurrencyUtils.subtract(customer.getCreditBalance(),
246	                        summary.getNextPurchaseCredit()));
247	                customerRepository.save(customer);
248	            }
249	        }
250	
251	        order.setStatus(OrderStatus.CANCELLED);
252	        order = orderRepository.save(order);
253	
254	        createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
255	
256	        return mapOrderToResponse(order);
257	    }
258	
259	    @Transactional(readOnly = true)
260	    public OrderResponse getOrder(String orderId) {
261	        Optional<Order> orderOpt = orderRepository.findById(orderId);
262	
263	        if (orderOpt.isEmpty()) {
264	            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
265	        }
266	
267	        return mapOrderToResponse(orderOpt.get());
268	    }
269	
270	    private List<Product> getProductsForOrder(List<Map<String, Object>> items) {
271	        List<Product> products = new java.util.ArrayList<>();
272	        for (var item : items) {
273	            String sku = (String) item.get("sku");
274	            Optional<Product> productOpt = productRepository.findById(sku);
275	            if (productOpt.isPresent()) {
276	                products.add(productOpt.get());
277	            }
278	        }
279	        return products;
280	    }
281	
282	    private void createNotification(String cpf, NotificationType type, String orderId) {
283	        Notification notification = Notification.builder()
284	                .customerCpf(cpf)
285	                .type(type)
286	                .orderId(orderId)
287	                .status(NotificationStatus.NEW)
288	                .createdAt(Instant.now())
289	                .build();
290	
291	        notificationRepository.save(notification);
292	    }
293	
294	    private OrderResponse mapOrderToResponse(Order order) {
295	        CheckoutSummary summary = deserializeSummary(order.getSummaryJson());
296	        List<Map<String, Object>> itemsList;
297	        try {
298	            @SuppressWarnings("unchecked")
299	            List<Map<String, Object>> items = objectMapper.readValue(order.getItemsJson(), List.class);
300	            itemsList = items;
301	        } catch (JsonProcessingException e) {
302	            throw new RuntimeException("Failed to deserialize items", e);
303	        }
304	
305	        List<OrderResponse.OrderItemResponse> items = itemsList.stream()
306	                .map(item -> OrderResponse.OrderItemResponse.builder()
307	                        .sku((String) item.get("sku"))
308	                        .quantity(((Number) item.get("quantity")).longValue())
309	                        .build())
310	                .toList();
311	
312	        return OrderResponse.builder()
313	                .id(order.getId())
314	                .status(order.getStatus())
315	                .createdAt(order.getCreatedAt())
316	                .summary(summary)
317	                .items(items)
318	                .trackingCode(order.getTrackingCode())
319	                .build();
320	    }
321	
322	    private String serializeSummary(CheckoutSummary summary) {
323	        try {
324	            return objectMapper.writeValueAsString(summary);
325	        } catch (JsonProcessingException e) {
326	            throw new RuntimeException("Failed to serialize summary", e);
327	        }
328	    }
329	
330	    private String serializeItems(List<CheckoutSummaryRequest.OrderItemRequest> items) {
331	        try {
332	            List<Map<String, Object>> itemMaps = items.stream()
333	                    .map(item -> {
334	                        Map<String, Object> map = new LinkedHashMap<>();
335	                        map.put("sku", item.getSku());
336	                        map.put("quantity", item.getQuantity());
337	                        return map;
338	                    })
339	                    .toList();
340	            return objectMapper.writeValueAsString(itemMaps);
341	        } catch (JsonProcessingException e) {
342	            throw new RuntimeException("Failed to serialize items", e);
343	        }
344	    }
345	
346	    private CheckoutSummary deserializeSummary(String json) {
347	        try {
348	            return objectMapper.readValue(json, CheckoutSummary.class);
349	        } catch (JsonProcessingException e) {
350	            throw new RuntimeException("Failed to deserialize summary", e);
351	        }
352	    }
353	}

