 90	            orderRepository.save(order);
 91	            throw new OrderServiceException("ORDER_EXPIRED", "Payment timeout", HttpStatus.CONFLICT);
 92	        }
 93	
 94	        CheckoutSummary summary = deserializeSummary(order.getSummaryJson());
 95	        List<Map<String, Object>> items;
 96	        try {
 97	            @SuppressWarnings("unchecked")
 98	            List<Map<String, Object>> itemsList = objectMapper.readValue(order.getItemsJson(), List.class);
 99	            items = itemsList;
100	        } catch (JsonProcessingException e) {
101	            throw new RuntimeException("Failed to deserialize items", e);
102	        }
103	
104	        List<Product> products = getProductsForOrder(items);
105	
106	        for (int i = 0; i < items.size(); i++) {
107	            @SuppressWarnings("unchecked")
108	            Map<String, Object> item = items.get(i);
109	            String sku = (String) item.get("sku");
110	            Long quantity = ((Number) item.get("quantity")).longValue();
111	
112	            Optional<Product> productOpt = productRepository.findById(sku);
113	            if (productOpt.isEmpty() || productOpt.get().getStock() < quantity) {
114	                order.setStatus(OrderStatus.CANCELLED);
115	                orderRepository.save(order);
116	                createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
117	                throw new OrderServiceException("INSUFFICIENT_STOCK", "Insufficient stock", HttpStatus.CONFLICT);
118	            }
119	        }
120	
121	        order.setStatus(OrderStatus.PAID);
122	        order.setPaidAt(paymentTime);
123	        order.setTransactionId(paymentRequest.getTransactionId());
124	        order = orderRepository.save(order);
125	
126	        for (int i = 0; i < items.size(); i++) {
127	            @SuppressWarnings("unchecked")
128	            Map<String, Object> item = items.get(i);
129	            String sku = (String) item.get("sku");
130	            Long quantity = ((Number) item.get("quantity")).longValue();
131	
132	            Product product = products.get(i);
133	            product.setStock(product.getStock() - quantity);
134	            productRepository.save(product);
135	        }
136	
137	        String cpf = order.getCustomerCpf();
138	        Optional<Customer> customerOpt = customerRepository.findById(cpf);
139	        Customer customer;
140	        if (customerOpt.isEmpty()) {
141	            customer = Customer.builder()
142	                    .cpf(cpf)
143	                    .creditBalance(summary.getNextPurchaseCredit())
144	                    .build();
145	        } else {
146	            customer = customerOpt.get();
147	            customer.setCreditBalance(CurrencyUtils.add(customer.getCreditBalance(),
148	                    summary.getNextPurchaseCredit()));
149	        }
150	        customerRepository.save(customer);
151	
152	        createNotification(cpf, NotificationType.PAYMENT_APPROVED, orderId);
153	
154	        return mapOrderToResponse(order);
155	    }
